        />

        <RegionMaterialRow
          title="Fines"
          stock={region.materials.fines.stock}
          amount={region.materials.fines.amount}
        />
      </div>
    </div>
  );
}

/* =========================================
   REGION MATERIAL ROW
========================================= */

function RegionMaterialRow({ title, stock, amount }) {
